DELETE FROM delivery
WHERE delivery_batch_id IN (
  SELECT delivery_batch_id FROM delivery_batch
  WHERE company_id = '00000000-0000-0000-0000-000000000001'
    AND batch_code IN ('SHP-0001', 'SHP-0002')
);

DELETE FROM delivery_batch
WHERE company_id = '00000000-0000-0000-0000-000000000001'
  AND batch_code IN ('SHP-0001', 'SHP-0002');

DELETE FROM address WHERE address_id IN (
  '00000000-0000-0000-0000-000000000401',
  '00000000-0000-0000-0000-000000000402',
  '00000000-0000-0000-0000-000000000403',
  '00000000-0000-0000-0000-000000000404',
  '00000000-0000-0000-0000-000000000405'
);

DELETE FROM customer WHERE customer_id IN (
  '00000000-0000-0000-0000-000000000301',
  '00000000-0000-0000-0000-000000000302',
  '00000000-0000-0000-0000-000000000303',
  '00000000-0000-0000-0000-000000000304',
  '00000000-0000-0000-0000-000000000305'
